-- TomoModForever 1.2.2 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_122_graphics"] = "New - Adventure > Graphics: nine hidden game settings for a prettier picture (denser vegetation seen farther away, sharper image, scenery and terrain detailed up to the horizon, water reflections, denser weather). All off by default; unticking puts back your own value.",
    ["wn_122_map"] = "New - Adventure comforts > World map: an option shows the areas you have not explored yet, tinted (colour of your choice) so you see where to go before you have been there.",
    ["wn_122_camp"] = "New - Adventure > Camp HUD: fires, camp objects and their bonuses are recognised by their spell IDs. The HUD also shows with the game's \"campfire nearby\" state, lists camp bonuses even if you already had them, and says when bonuses are ready again. Pointing at a camp object shows its bonus, and whether it is active or on cooldown.",
    ["wn_122_trainer"] = "New - Adventure > Class trainer reminder: the spells of every Forever class trainer are built in, so the panel lists what you can learn from level 1, before any visit, checked against your spellbook (a spell missed at an earlier level stays listed). A visit to the trainer still brings the real prices and talent ranks.",
    ["wn_122_tabs"] = "Fixed - Chat: whisper tabs now appear in the TomoMod tab row (they were missing and Blizzard's tab showed behind the panel). Tabs keep Blizzard's order, the open tab always follows the window you type in, and an incoming whisper no longer takes you off the tab you are reading.",
    ["wn_122_overflow"] = "New - Chat: a + button after the tabs opens a new tab: Guild, Group, Whispers, Trade (in cities), Loot, or any name you type. When the tabs no longer fit, the last ones go into a list at the end of the row, with an unread dot.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_122_graphics"] = "Nouveau - Aventure > Graphismes : neuf réglages cachés du jeu pour un rendu plus joli (végétation plus dense et visible plus loin, image plus nette, décor et relief détaillés jusqu'à l'horizon, reflets de l'eau, météo plus dense). Tout est désactivé de base ; décocher remet ta propre valeur.",
    ["wn_122_map"] = "Nouveau - Confort d'aventure > Carte du monde : une option affiche les zones que tu n'as pas encore explorées, teintées (couleur au choix), pour voir où aller avant d'y être passé.",
    ["wn_122_camp"] = "Nouveau - Aventure > HUD de campement : les feux, les objets du camp et leurs bonus sont reconnus par leur ID de sort. Le HUD s'affiche aussi avec l'état « feu de camp proche » du jeu, liste les bonus du camp même si tu les avais déjà, et indique quand les bonus seront de nouveau disponibles. Survoler un objet du camp montre son bonus, et s'il est actif ou en recharge.",
    ["wn_122_trainer"] = "Nouveau - Aventure > Rappel du maître de classe : les sorts de chaque maître de classe de Forever sont intégrés, le panneau liste donc ce que tu peux apprendre dès le niveau 1, avant toute visite, en le comparant à ton grimoire (un sort oublié à un niveau précédent reste dans la liste). Une visite au maître apporte toujours les prix réels et les rangs de talents.",
    ["wn_122_tabs"] = "Corrigé - Chat : les onglets de chuchotement apparaissent dans la rangée d'onglets TomoMod (ils manquaient et l'onglet Blizzard se voyait derrière le panneau). Les onglets gardent l'ordre de Blizzard, l'onglet ouvert suit toujours la fenêtre où tu écris, et un chuchotement reçu ne te sort plus de l'onglet que tu lis.",
    ["wn_122_overflow"] = "Nouveau - Chat : un bouton + après les onglets ouvre un nouvel onglet : Guilde, Groupe, Chuchotements, Commerce (en ville), Butin, ou le nom que tu tapes. Quand les onglets ne tiennent plus, les derniers passent dans une liste au bout de la rangée, avec un point de non-lu.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_122_graphics"] = "Neu - Abenteuer > Grafik: neun versteckte Spieleinstellungen für ein schöneres Bild (dichtere, weiter sichtbare Vegetation, schärferes Bild, Landschaft und Gelände bis zum Horizont detailliert, Wasserspiegelungen, dichteres Wetter). Standardmäßig alles aus; Abwählen stellt deinen eigenen Wert wieder her.",
    ["wn_122_map"] = "Neu - Abenteuer-Komfort > Weltkarte: Eine Option zeigt die noch nicht erkundeten Gebiete, eingefärbt (Farbe wählbar), damit du siehst, wohin es geht, bevor du dort warst.",
    ["wn_122_camp"] = "Neu - Abenteuer > Lager-HUD: Feuer, Lagerobjekte und ihre Boni werden an ihrer Zauber-ID erkannt. Das HUD erscheint auch beim Spielzustand „Lagerfeuer in der Nähe“, listet Lagerboni auch dann, wenn du sie schon hattest, und zeigt, wann die Boni wieder bereit sind. Beim Zeigen auf ein Lagerobjekt siehst du seinen Bonus und ob er aktiv ist oder abklingt.",
    ["wn_122_trainer"] = "Neu - Abenteuer > Lehrer-Erinnerung: Die Zauber aller Forever-Klassenlehrer sind eingebaut, das Fenster zeigt also ab Stufe 1 und vor jedem Besuch, was du lernen kannst, abgeglichen mit deinem Zauberbuch (ein auf einer früheren Stufe verpasster Zauber bleibt in der Liste). Ein Besuch beim Lehrer liefert weiterhin die echten Preise und Talentränge.",
    ["wn_122_tabs"] = "Behoben - Chat: Flüster-Tabs erscheinen jetzt in der TomoMod-Tableiste (sie fehlten, und Blizzards Tab war hinter dem Fenster zu sehen). Die Tabs behalten Blizzards Reihenfolge, der offene Tab folgt immer dem Fenster, in das du schreibst, und ein eingehendes Flüstern reißt dich nicht mehr aus dem Tab, den du liest.",
    ["wn_122_overflow"] = "Neu - Chat: Ein +-Knopf hinter den Tabs öffnet einen neuen Tab: Gilde, Gruppe, Flüstern, Handel (in Städten), Beute oder ein eigener Name. Passen die Tabs nicht mehr, kommen die letzten in eine Liste am Ende der Leiste, mit Ungelesen-Punkt.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_122_graphics"] = "Nuevo - Aventura > Gráficos: nueve ajustes ocultos del juego para una imagen más bonita (vegetación más densa y visible más lejos, imagen más nítida, escenario y relieve detallados hasta el horizonte, reflejos del agua, clima más denso). Todo desactivado por defecto; desmarcar devuelve tu propio valor.",
    ["wn_122_map"] = "Nuevo - Comodidades de aventura > Mapa del mundo: una opción muestra las zonas que aún no has explorado, teñidas (color a elegir), para ver adónde ir antes de haber pasado por allí.",
    ["wn_122_camp"] = "Nuevo - Aventura > HUD de campamento: las hogueras, los objetos del campamento y sus bonificaciones se reconocen por su ID de hechizo. El HUD también aparece con el estado «hoguera cercana» del juego, muestra las bonificaciones del campamento aunque ya las tuvieras e indica cuándo vuelven a estar disponibles. Al señalar un objeto del campamento verás su bonificación y si está activa o en reutilización.",
    ["wn_122_trainer"] = "Nuevo - Aventura > Aviso de instructor: los hechizos de cada instructor de clase de Forever vienen incluidos, así que el panel muestra lo que puedes aprender desde el nivel 1, antes de cualquier visita, comparado con tu libro de hechizos (un hechizo olvidado en un nivel anterior sigue en la lista). Visitar al instructor sigue dando los precios reales y los rangos de talentos.",
    ["wn_122_tabs"] = "Corregido - Chat: las pestañas de susurros aparecen en la fila de pestañas de TomoMod (faltaban y la pestaña de Blizzard se veía detrás del panel). Las pestañas siguen el orden de Blizzard, la pestaña abierta sigue siempre a la ventana en la que escribes y un susurro recibido ya no te saca de la pestaña que lees.",
    ["wn_122_overflow"] = "Nuevo - Chat: un botón + tras las pestañas abre una pestaña nueva: Hermandad, Grupo, Susurros, Comercio (en ciudades), Botín o el nombre que escribas. Cuando las pestañas ya no caben, las últimas pasan a una lista al final de la fila, con un punto de no leído.",
})

TomoMod_RegisterLocale("itIT", {
    ["wn_122_graphics"] = "Nuovo - Avventura > Grafica: nove impostazioni nascoste del gioco per un'immagine più bella (vegetazione più fitta e visibile più lontano, immagine più nitida, scenario e terreno dettagliati fino all'orizzonte, riflessi dell'acqua, meteo più denso). Tutto disattivato di base; togliere la spunta rimette il tuo valore.",
    ["wn_122_map"] = "Nuovo - Comodità d'avventura > Mappa del mondo: un'opzione mostra le zone che non hai ancora esplorato, colorate (colore a scelta), per vedere dove andare prima di esserci passato.",
    ["wn_122_camp"] = "Nuovo - Avventura > HUD dell'accampamento: falò, oggetti dell'accampamento e i loro bonus sono riconosciuti dal loro ID dell'incantesimo. L'HUD appare anche con lo stato «falò vicino» del gioco, elenca i bonus dell'accampamento anche se li avevi già e indica quando i bonus tornano disponibili. Puntando un oggetto dell'accampamento vedi il suo bonus, e se è attivo o in ricarica.",
    ["wn_122_trainer"] = "Nuovo - Avventura > Promemoria istruttore: gli incantesimi di ogni istruttore di classe di Forever sono inclusi, quindi il pannello elenca ciò che puoi imparare dal livello 1, prima di ogni visita, confrontandolo con il tuo libro degli incantesimi (un incantesimo saltato a un livello precedente resta nell'elenco). Una visita all'istruttore porta sempre i prezzi reali e i gradi dei talenti.",
    ["wn_122_tabs"] = "Corretto - Chat: le schede dei sussurri compaiono nella fila di schede di TomoMod (mancavano e la scheda Blizzard si vedeva dietro il pannello). Le schede seguono l'ordine di Blizzard, la scheda aperta segue sempre la finestra in cui scrivi e un sussurro ricevuto non ti porta più via dalla scheda che stai leggendo.",
    ["wn_122_overflow"] = "Nuovo - Chat: un pulsante + dopo le schede apre una nuova scheda: Gilda, Gruppo, Sussurri, Commercio (in città), Bottino o il nome che scrivi. Quando le schede non ci stanno più, le ultime passano in un elenco in fondo alla fila, con un punto di non letto.",
})

